// =============================================================================
// PLUGIN ENTRY: identity and typed schema seed
// =============================================================================

const PLUGIN_NAME: &str = "memory";
const PLUGIN_VERSION: &str = "1.0.0";
const PLUGIN_CATEGORY: &str = "service";
const PLUGIN_DESCRIPTION: &str =
    "Persistent knowledge-graph memory service — entity/relation graph stored in CozoDB, \
     semantic search over observations via Qdrant. Schema grounded in official MCP memory \
     server tool surface and dual-backend architecture.";
const PLUGIN_DISPLAY_NAME: &str = "GB.Memory";

const ENV_DIR: &str = "/etc/s6/sv/op-memory/env";
const RUNTIME_ENV_DIR: &str = "/run/service/op-memory/env";

/// Qdrant REST endpoint (local container).
const DEFAULT_QDRANT_REST: &str = "http://127.0.0.1:6333";
/// CozoDB HTTP endpoint (local container).
const DEFAULT_COZODB_URL: &str = "http://127.0.0.1:2088";
/// Qdrant collection for observation vectors.
const DEFAULT_MEMORY_COLLECTION: &str = "memory_observations";

// ── Deployment config ────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct MemoryConfig {
