    pub qdrant_rest: String,
    #[serde(default = "default_cozodb_url")]
    pub cozodb_url: String,
    #[serde(default = "default_memory_collection")]
    pub qdrant_collection: String,
    #[serde(default = "default_embed_model")]
    pub embed_model: String,
    #[serde(default = "default_true")]
    pub enabled: bool,
}

fn default_qdrant_rest() -> String {
    DEFAULT_QDRANT_REST.into()
}
fn default_cozodb_url() -> String {
    DEFAULT_COZODB_URL.into()
}
fn default_memory_collection() -> String {
    DEFAULT_MEMORY_COLLECTION.into()
}
