// =============================================================================
// PLUGIN EXIT: publish the single PluginSchema contract
// =============================================================================

pub(crate) fn memory_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(MemoryState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME,
        PLUGIN_VERSION,
        PLUGIN_DESCRIPTION,
        &root,
    );
    schema.category = PLUGIN_CATEGORY.to_string();
    schema.display_name = Some(PLUGIN_DISPLAY_NAME.to_string());

    // ── Entity / observation CRUD methods (MCP memory server surface) ─────────
    schema.methods.insert(
        "create_entities".to_string(),
        method_decl_from_schemars_with_output::<CreateEntitiesInput, CreateEntitiesOutput>(
            "create_entities",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.entities.create@v1",
        ),
    );
    schema.methods.insert(
        "create_relations".to_string(),
        method_decl_from_schemars_with_output::<CreateRelationsInput, CreateRelationsOutput>(
            "create_relations",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.relations.create@v1",
        ),
    );
    schema.methods.insert(
        "add_observations".to_string(),
        method_decl_from_schemars_with_output::<AddObservationsInput, AddObservationsOutput>(
            "add_observations",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.observations.add@v1",
        ),
    );
    schema.methods.insert(
        "delete_entities".to_string(),
        method_decl_from_schemars_with_output::<DeleteEntitiesInput, DeleteEntitiesOutput>(
            "delete_entities",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.entities.delete@v1",
        ),
    );
    schema.methods.insert(
        "delete_observations".to_string(),
        method_decl_from_schemars_with_output::<DeleteObservationsInput, DeleteObservationsOutput>(
            "delete_observations",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.observations.delete@v1",
        ),
    );
    schema.methods.insert(
        "delete_relations".to_string(),
        method_decl_from_schemars_with_output::<DeleteRelationsInput, DeleteRelationsOutput>(
            "delete_relations",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.relations.delete@v1",
        ),
    );

    // ── Graph read methods (MCP memory server surface) ────────────────────────
    schema.methods.insert(
        "read_graph".to_string(),
        method_decl_from_schemars_with_output::<ReadGraphInput, ReadGraphOutput>(
            "read_graph",
            SideEffect::Read,
            true,
            "memory.read",
            "obs.service.memory.graph.read@v1",
        ),
    );
    schema.methods.insert(
        "search_nodes".to_string(),
        method_decl_from_schemars_with_output::<SearchNodesInput, SearchNodesOutput>(
            "search_nodes",
            SideEffect::Read,
            true,
            "memory.read",
            "obs.service.memory.nodes.search@v1",
        ),
    );
    schema.methods.insert(
        "open_nodes".to_string(),
        method_decl_from_schemars_with_output::<OpenNodesInput, OpenNodesOutput>(
            "open_nodes",
            SideEffect::Read,
            true,
            "memory.read",
            "obs.service.memory.nodes.open@v1",
        ),
    );

    // ── Extended graph traversal method ───────────────────────────────────────
    schema.methods.insert(
        "graph_traverse".to_string(),
        method_decl_from_schemars_with_output::<GraphTraverseInput, GraphTraverseOutput>(
            "graph_traverse",
            SideEffect::Read,
            false,
            "memory.read",
            "obs.service.memory.graph.traverse@v1",
        ),
    );

    // ── Service management methods ────────────────────────────────────────────
    schema.methods.insert(
        "get_health".to_string(),
        method_decl_from_schemars_with_output::<(), MemoryHealthOutput>(
            "get_health",
            SideEffect::Read,
            true,
            "memory.read",
            "obs.service.memory.health@v1",
        ),
    );
    schema.methods.insert(
        "restart_service".to_string(),
        method_decl_from_schemars_with_output::<(), RestartServiceOutput>(
            "restart_service",
            SideEffect::Mutation,
            true,
            "memory.invoke",
            "mut.service.memory.restart@v1",
        ),
    );

    schema
}

