            };
        }
        diff!(qdrant_rest, "qdrant_rest");
        diff!(cozodb_url, "cozodb_url");
        diff!(qdrant_collection, "qdrant_collection");
        diff!(embed_model, "embed_model");
        diff!(enabled, "enabled");

        Ok(StateDiff {
            plugin: self.name().into(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes = Vec::new();
        let mut errors = Vec::new();
        let mut needs_reload = false;

        for action in &diff.actions {
            if let StateAction::Modify {
                resource,
                changes: val,
            } = action
            {
                let result: Result<()> = match resource.as_str() {
                    "qdrant_rest" => {
                        if let Some(s) = val.as_str() {
                            Self::write_env("QDRANT_REST_URL", s).await?;
                            needs_reload = true;
                            Ok(())
                        } else {
                            Err(anyhow::anyhow!("qdrant_rest must be a string"))
                        }
                    }
                    "cozodb_url" => {
                        if let Some(s) = val.as_str() {
                            Self::write_env("COZODB_URL", s).await?;
                            needs_reload = true;
                            Ok(())
                        } else {
                            Err(anyhow::anyhow!("cozodb_url must be a string"))
                        }
                    }
                    "qdrant_collection" => {
                        if let Some(s) = val.as_str() {
                            Self::write_env("MEMORY_QDRANT_COLLECTION", s).await?;
                            needs_reload = true;
                            Ok(())
                        } else {
                            Err(anyhow::anyhow!("qdrant_collection must be a string"))
                        }
                    }
                    "embed_model" => {
                        if let Some(s) = val.as_str() {
                            Self::write_env("MEMORY_EMBED_MODEL", s).await?;
                            needs_reload = true;
                            Ok(())
                        } else {
                            Err(anyhow::anyhow!("embed_model must be a string"))
                        }
                    }
                    "enabled" => {
                        if val.as_bool() == Some(false) {
                            Self::write_env("MEMORY_DISABLED", "1").await?;
                        } else {
                            let _ =
                                tokio::fs::remove_file(format!("{ENV_DIR}/MEMORY_DISABLED")).await;
                        }
                        needs_reload = true;
                        Ok(())
                    }
                    other => Err(anyhow::anyhow!("unknown memory field: {other}")),
                };
                match result {
                    Ok(()) => changes.push(format!("memory.{resource} updated")),
                    Err(e) => errors.push(format!("memory.{resource}: {e}")),
                }
            }
        }

        if needs_reload && errors.is_empty() {
            if let Err(e) = Self::reload_service().await {
                tracing::warn!("memory reload: {e}");
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied: changes,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: format!("memory-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().into(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!(null),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let old: MemoryConfig =
            simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;
        let desired = simd_json::serde::to_owned_value(&old)?;
        let current = simd_json::json!(null);
        let diff = self.calculate_diff(&current, &desired).await?;
        self.apply_state(&diff).await?;
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

// =============================================================================
// SCHEMA TYPES: grounded in MCP memory server + dual-backend conventions
// =============================================================================

/// An entity in the knowledge graph.
///
/// Mirrors the official MCP memory server entity structure:
/// `{ name: string, entityType: string, observations: string[] }`
///
/// Stored in CozoDB as: `*memory_entities[name, entity_type, created_at]`
/// Observations stored in: `*memory_observations[entity_name, observation, created_at]`
/// Observation vectors stored in Qdrant collection `memory_observations`
/// with payload: `{ entity_name, entity_type, observation, context }`.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct MemoryEntity {
    #[schemars(description = "Unique entity identifier (e.g. 'John_Smith', 'WireGuard_Protocol')")]
    pub name: String,
    #[schemars(description = "Entity type classification (e.g. 'person', 'organization', 'concept', 'project')")]
    pub entity_type: String,
    #[schemars(description = "Atomic facts about this entity (one fact per string)")]
    pub observations: Vec<String>,
}

/// A directed relation between two entities.
///
/// Mirrors the official MCP memory server relation structure:
/// `{ from: string, to: string, relationType: string }` (always active voice).
///
/// Stored in CozoDB as: `*memory_relations[from_entity, to_entity, relation_type, created_at]`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct MemoryRelation {
    #[schemars(description = "Source entity name")]
    pub from: String,
    #[schemars(description = "Target entity name")]
    pub to: String,
    #[schemars(description = "Relationship type in active voice (e.g. 'works_at', 'depends_on', 'implements')")]
    pub relation_type: String,
}

/// An observation addition request for an existing entity.
///
/// Mirrors the official MCP memory server add_observations input:
/// `{ entityName: string, contents: string[] }`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ObservationAddition {
    #[schemars(description = "Name of the entity to add observations to (must already exist)")]
    pub entity_name: String,
    #[schemars(description = "New observations to add (atomic facts, one per string)")]
    pub contents: Vec<String>,
}

/// An observation deletion request.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ObservationDeletion {
    #[schemars(description = "Name of the entity to remove observations from")]
    pub entity_name: String,
    #[schemars(description = "Exact observation strings to remove")]
    pub observations: Vec<String>,
}

/// Search mode for node search.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum MemorySearchMode {
    /// Semantic search via Qdrant (embeds query, searches memory_observations collection)
    Semantic,
    /// Keyword search across entity names, types, and observation content in CozoDB
    Keyword,
    /// Fused: semantic + keyword, deduplicated by entity name
    Fused,
}

impl Default for MemorySearchMode {
    fn default() -> Self {
        Self::Fused
    }
}

fn default_search_mode() -> MemorySearchMode {
    MemorySearchMode::default()
}

// ── Default helpers ──────────────────────────────────────────────────────────

fn default_search_limit() -> u8 {
    10
}

fn default_score_threshold() -> f32 {
    0.0
}

