fn example_entity_name() -> String {
    "WireGuard_Protocol".to_string()
}

fn example_entity_type() -> String {
    "concept".to_string()
}

fn example_search_query() -> String {
    "cryptographic identity verification".to_string()
}

// =============================================================================
// INPUT / OUTPUT STRUCTS: one per method, mirroring MCP memory server tools
// =============================================================================

// ── create_entities ───────────────────────────────────────────────────────────

/// Input for create_entities: create multiple new entities in the knowledge graph.
///
/// MCP memory server: `create_entities(entities: Entity[])`
/// Ignores entities whose name already exists (idempotent).
///
/// Implementation:
///   - CozoDB: inserts rows into `memory_entities` and `memory_observations`
///   - Qdrant: upserts observation vectors into `memory_observations` collection
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CreateEntitiesInput {
    #[schemars(description = "Entities to create. Each entity has a name, type, and initial observations.")]
    pub entities: Vec<MemoryEntity>,
}

/// Output for create_entities.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CreateEntitiesOutput {
    pub created: Vec<String>,
    pub skipped_existing: Vec<String>,
    pub observations_indexed: u64,
}

// ── create_relations ──────────────────────────────────────────────────────────

/// Input for create_relations: create directed relations between existing entities.
///
/// MCP memory server: `create_relations(relations: Relation[])`
/// Skips duplicate relations (idempotent).
///
/// Implementation:
///   - CozoDB: inserts rows into `memory_relations`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CreateRelationsInput {
    #[schemars(description = "Relations to create. Each relation has from, to, and relation_type (active voice).")]
    pub relations: Vec<MemoryRelation>,
}

/// Output for create_relations.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CreateRelationsOutput {
    pub created: u32,
    pub skipped_duplicates: u32,
}

// ── add_observations ──────────────────────────────────────────────────────────

/// Input for add_observations: add new observations to existing entities.
///
/// MCP memory server: `add_observations(observations: ObservationInput[])`
/// Fails if the target entity does not exist.
///
/// Implementation:
///   - CozoDB: inserts rows into `memory_observations`
///   - Qdrant: upserts new observation vectors into `memory_observations` collection
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct AddObservationsInput {
    #[schemars(description = "Observations to add. Each entry targets an existing entity by name.")]
    pub observations: Vec<ObservationAddition>,
}

/// Per-entity result for add_observations.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ObservationAddResult {
    pub entity_name: String,
    pub added: Vec<String>,
    pub error: Option<String>,
}

/// Output for add_observations.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct AddObservationsOutput {
    pub results: Vec<ObservationAddResult>,
    pub total_added: u64,
    pub errors: Vec<String>,
}

// ── delete_entities ───────────────────────────────────────────────────────────

/// Input for delete_entities: remove entities and all their associated data.
///
/// MCP memory server: `delete_entities(entityNames: string[])`
/// Cascading deletion: removes the entity, all its observations, and all
/// relations where it appears as `from` or `to`.
///
/// Implementation:
///   - CozoDB: deletes from `memory_entities`, `memory_observations`, `memory_relations`
///   - Qdrant: deletes all points with `entity_name` payload matching deleted entities
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteEntitiesInput {
    #[schemars(description = "Names of entities to delete (cascading: removes observations and relations)")]
    pub entity_names: Vec<String>,
}

/// Output for delete_entities.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteEntitiesOutput {
    pub deleted: Vec<String>,
    pub not_found: Vec<String>,
    pub relations_removed: u32,
    pub observations_removed: u32,
    pub qdrant_points_removed: u64,
}

// ── delete_observations ───────────────────────────────────────────────────────

/// Input for delete_observations: remove specific observations from entities.
///
/// MCP memory server: `delete_observations(deletions: { entityName, observations }[])`
/// Silent if the observation does not exist.
///
/// Implementation:
///   - CozoDB: deletes matching rows from `memory_observations`
///   - Qdrant: deletes matching points from `memory_observations` collection
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteObservationsInput {
    #[schemars(description = "Observations to remove. Each entry targets an entity and lists exact observation strings.")]
    pub deletions: Vec<ObservationDeletion>,
}

/// Output for delete_observations.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteObservationsOutput {
    pub removed: u32,
    pub not_found: u32,
    pub qdrant_points_removed: u64,
}

// ── delete_relations ──────────────────────────────────────────────────────────

/// Input for delete_relations: remove specific relations from the graph.
///
/// MCP memory server: `delete_relations(relations: Relation[])`
/// Silent if the relation does not exist.
///
/// Implementation:
///   - CozoDB: deletes matching rows from `memory_relations`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteRelationsInput {
    #[schemars(description = "Relations to remove. Each entry must match from, to, and relation_type exactly.")]
    pub relations: Vec<MemoryRelation>,
}

/// Output for delete_relations.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct DeleteRelationsOutput {
    pub removed: u32,
    pub not_found: u32,
}

// ── read_graph ────────────────────────────────────────────────────────────────

/// Input for read_graph: read the entire knowledge graph.
///
/// MCP memory server: `read_graph()` — no input required.
/// Returns all entities, their observations, and all relations.
///
/// Implementation:
///   - CozoDB: `?[name, type] := *memory_entities[name, type, _]` and
///     `?[from, to, rel] := *memory_relations[from, to, rel, _]`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ReadGraphInput {
    #[schemars(description = "Optional entity type filter (e.g. 'person', 'concept')")]
    pub entity_type_filter: Option<String>,
    #[schemars(description = "Maximum entities to return (default: all)")]
    pub limit: Option<u32>,
}

/// Full entity with all observations, as returned by read_graph / open_nodes.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct MemoryEntityFull {
    pub name: String,
    pub entity_type: String,
    pub observations: Vec<String>,
    pub created_at: Option<String>,
}

/// Output for read_graph.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ReadGraphOutput {
    pub entities: Vec<MemoryEntityFull>,
    pub relations: Vec<MemoryRelation>,
    pub entity_count: usize,
    pub relation_count: usize,
}

// ── search_nodes ──────────────────────────────────────────────────────────────

/// Input for search_nodes: search for entities by query.
///
/// MCP memory server: `search_nodes(query: string)`
/// Searches across entity names, entity types, and observation content.
///
/// Implementation (fused mode):
///   - Qdrant: embed query, search `memory_observations` collection,
///     group results by `entity_name` payload field
///   - CozoDB: keyword search across `memory_entities` and `memory_observations`
///   - Merge and deduplicate by entity name
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SearchNodesInput {
    #[schemars(
        description = "Search query — natural language or keyword",
        example = example_search_query()
    )]
    pub query: String,

    #[serde(default = "default_search_mode")]
    #[schemars(description = "Search mode: semantic | keyword | fused (default: fused)")]
    pub mode: MemorySearchMode,

    #[schemars(description = "Filter by entity type (e.g. 'person', 'concept')")]
    pub entity_type_filter: Option<String>,

    #[serde(default = "default_search_limit")]
    #[schemars(
        range(min = 1, max = 100),
        description = "Maximum entities to return (default 10)"
    )]
    pub limit: u8,

    #[serde(default = "default_score_threshold")]
    #[schemars(
        range(min = 0.0, max = 1.0),
        description = "Minimum Qdrant similarity score threshold (default 0.0)"
    )]
    pub score_threshold: f32,
}

/// Output for search_nodes.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SearchNodesOutput {
    pub entities: Vec<MemoryEntityFull>,
    pub relations: Vec<MemoryRelation>,
    pub count: usize,
    pub mode_used: String,
}

// ── open_nodes ────────────────────────────────────────────────────────────────

/// Input for open_nodes: retrieve specific entities by name.
///
/// MCP memory server: `open_nodes(names: string[])`
/// Returns the requested entities and all relations between them.
/// Silently skips non-existent entity names.
///
/// Implementation:
///   - CozoDB: `?[name, type, obs] := *memory_entities[name, type, _], name in $names`
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct OpenNodesInput {
    #[schemars(description = "Entity names to retrieve")]
    pub names: Vec<String>,
    #[serde(default = "default_false")]
    #[schemars(description = "Also include all relations involving any of the requested entities")]
    pub include_all_relations: bool,
}

/// Output for open_nodes.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct OpenNodesOutput {
    pub entities: Vec<MemoryEntityFull>,
    pub relations: Vec<MemoryRelation>,
    pub not_found: Vec<String>,
}

// ── graph_traverse ────────────────────────────────────────────────────────────

/// Input for graph_traverse: traverse the knowledge graph from a starting entity.
///
/// Uses CozoDB recursive Datalog rules to walk the `memory_relations` graph.
/// Supports BFS/DFS up to a configurable depth.
