    #[schemars(description = "Maximum traversal depth (default 2, max 10)")]
    pub max_depth: Option<u8>,

    #[schemars(description = "Filter traversal to specific relation types (e.g. ['depends_on', 'implements'])")]
    pub relation_type_filter: Option<Vec<String>>,

    #[schemars(description = "Filter traversal to specific entity types")]
    pub entity_type_filter: Option<Vec<String>>,

    #[serde(default = "default_false")]
    #[schemars(description = "Follow relations in both directions (undirected traversal)")]
    pub bidirectional: bool,
}

/// A node in the traversal result.
