// =============================================================================
// PLUGIN EXIT: publish the single PluginSchema contract
// =============================================================================

pub(crate) fn memory_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(MemoryState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME,
        PLUGIN_VERSION,
        PLUGIN_DESCRIPTION,
        &root,
    );
    schema.category = PLUGIN_CATEGORY.to_string();
    schema.display_name = Some(PLUGIN_DISPLAY_NAME.to_string());

    // ── Entity / observation CRUD methods (MCP memory server surface) ─────────
    schema.methods.insert(
        "create_entities".to_string(),
        method_decl_from_schemars_with_output::<CreateEntitiesInput, CreateEntitiesOutput>(
            "create_entities",
            SideEffect::Mutation,
            false,
            "memory.invoke",
            "mut.service.memory.entities.create@v1",
        ),
    );
