//!   - Gemini API grounding with Google Search (ai.google.dev/gemini-api/docs/google-search)
//!   - Gemini API model list (ai.google.dev/gemini-api/docs/models/gemini)
//!   - GenerationConfig, SafetySetting, Tool, ToolConfig official types
//!   - Internal op-cognitive-mcp GeminiTool / GeminiDeepResearchTool definitions
//!
//! The canonical schema lives in `gemini_schema()` below.

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
