// =============================================================================
// PLUGIN ENTRY: identity and typed schema seed
// =============================================================================

const PLUGIN_NAME: &str = "gemini";
const PLUGIN_VERSION: &str = "1.0.0";
const PLUGIN_CATEGORY: &str = "service";
const PLUGIN_DESCRIPTION: &str =
    "Gemini AI service — content generation, grounded search, deep research, and model \
     management. Schema grounded in official Gemini API generateContent spec.";
const PLUGIN_DISPLAY_NAME: &str = "GB.Gemini";

const ENV_DIR: &str = "/etc/s6/sv/op-gemini/env";
const RUNTIME_ENV_DIR: &str = "/run/service/op-gemini/env";

/// Default Gemini API base URL.
const DEFAULT_API_BASE: &str = "https://generativelanguage.googleapis.com";
/// Default model for standard generation.
const DEFAULT_MODEL: &str = "gemini-2.5-flash";
/// Default model for deep research (highest capability).
const DEFAULT_RESEARCH_MODEL: &str = "gemini-2.5-pro";

// ── Deployment config ────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct GeminiConfig {
