//!
//! Tracks and manages the op-notebooklm service: authentication state,
//! notebook library, source management, and studio content generation.
//! Publishes live state to D-Bus under `/opdbus/v1/plugins/notebooklm`
//! so that `register_plugin_projection_tools` can expose it as MCP tools.
//!
//! Schema is grounded in:
//!   - NotebookLM Enterprise REST API (discoveryengine.googleapis.com/v1alpha)
//!   - Community MCP server tool surface (jacob-bd/notebooklm-mcp-cli, 29 tools)
//!   - Internal op-cognitive-mcp NotebookLM tool definitions
//!
//! The canonical schema (every gRPC method, every MCP tool, every
//! request/response field) lives in the `notebooklm_schema()` function below.

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::PluginSchema;
use op_state_store::SideEffect;
use serde::{Deserialize, Serialize};
use simd_json::prelude::ValueAsScalar;
use simd_json::{prelude::*, OwnedValue as Value};

use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;

// =============================================================================
// PLUGIN ENTRY: identity and typed schema seed
// =============================================================================

const PLUGIN_NAME: &str = "notebooklm";
const PLUGIN_VERSION: &str = "1.0.0";
const PLUGIN_CATEGORY: &str = "service";
const PLUGIN_DESCRIPTION: &str =
    "NotebookLM service — notebook CRUD, source management, AI query, and studio content \
     generation. Schema grounded in NotebookLM Enterprise API and MCP tool surface.";
const PLUGIN_DISPLAY_NAME: &str = "GB.NotebookLm";

const S6_SV_PATH: &str = "/run/service/op-notebooklm";
const ENV_DIR: &str = "/etc/s6/sv/op-notebooklm/env";
const RUNTIME_ENV_DIR: &str = "/run/service/op-notebooklm/env";
const DEFAULT_ENDPOINT: &str = "https://notebooklm.google.com";

// ── Deployment config ────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct NotebookLmConfig {
    #[serde(default = "default_endpoint")]
    pub endpoint: String,
    #[serde(default = "default_true")]
    pub enabled: bool,
    /// Chrome profile path used for cookie-based auth
    #[serde(default)]
    pub chrome_profile: Option<String>,
}

fn default_endpoint() -> String {
    DEFAULT_ENDPOINT.into()
}
fn default_true() -> bool {
    true
}

impl Default for NotebookLmConfig {
    fn default() -> Self {
        Self {
            endpoint: default_endpoint(),
            enabled: true,
            chrome_profile: None,
        }
    }
}

// ── Plugin struct ────────────────────────────────────────────────────────────

pub struct NotebookLmPlugin;

impl NotebookLmPlugin {
    pub fn new() -> Self {
        Self
    }

    fn read_env(key: &str) -> Option<String> {
        std::fs::read_to_string(format!("{ENV_DIR}/{key}"))
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    }

    fn current_config() -> NotebookLmConfig {
        NotebookLmConfig {
            endpoint: Self::read_env("NOTEBOOKLM_ENDPOINT").unwrap_or_else(default_endpoint),
            enabled: Self::read_env("NOTEBOOKLM_DISABLED").is_none(),
            chrome_profile: Self::read_env("NOTEBOOKLM_CHROME_PROFILE"),
        }
    }

    async fn write_env(key: &str, value: &str) -> Result<()> {
        tokio::fs::create_dir_all(ENV_DIR)
            .await
            .context("create notebooklm env dir")?;
        tokio::fs::write(format!("{ENV_DIR}/{key}"), value)
            .await
            .with_context(|| format!("write env {key}"))?;
        if let Ok(()) = tokio::fs::create_dir_all(RUNTIME_ENV_DIR).await {
            let _ = tokio::fs::write(format!("{RUNTIME_ENV_DIR}/{key}"), value).await;
        }
        Ok(())
    }

    async fn reload_service() -> Result<()> {
        Self::reload_service_dbus().await
    }

    async fn reload_service_dbus() -> Result<()> {
        let conn = zbus::Connection::system()
            .await
            .context("Failed to connect to system D-Bus")?;

        let reply = conn
            .call_method(
                Some("opdbus.v1"),
                "/org/opdbus/v1/plugins/s6/systemctl",
                Some("opdbus.v1.S6.Systemctl"),
                "reload",
                &("op-notebooklm",),
            )
            .await
            .context("Failed to call reload on s6-systemctl D-Bus service")?;

        let (success, message): (bool, String) = reply.body().deserialize().map_err(|e| {
            anyhow::anyhow!("Failed to deserialize s6-systemctl reload response: {}", e)
        })?;

        if success {
            tracing::info!("Reloaded op-notebooklm via D-Bus: {}", message);
            Ok(())
        } else {
            Err(anyhow::anyhow!("s6-systemctl reload failed: {}", message))
        }
    }
}

impl Default for NotebookLmPlugin {
    fn default() -> Self {
        Self::new()
    }
