//! D-Bus interface for the Cognitive MCP method dispatcher.
//!
//! service:   org.opdbus.v1
//! object:    /org/opdbus/v1/plugins/cognitive_mcp
//! interface: org.opdbus.v1.plugins.CognitiveMcp
//!
//! Methods:
//!   CallMethod(s plugin_id, s method, s args_json) -> s
//!     Dispatches a schema-declared method call to the appropriate shuttle or
//!     pipeline. This is the execution bridge between the gRPC bridge's
//!     `MutationEngine::dispatch_method_call` and the cognitive backends.
//!
//!   ListTools() -> s
//!     JSON array [{name, description, category}] from the tool registry.
//!
//!   GetToolSchema(s name) -> s
//!     JSON input schema for a tool, or "null".
//!
//!   CallTool(s name, s args_json) -> s
//!     Legacy tool-registry execution path (pre-schema tools).

use crate::method_dispatch::CognitiveMethodDispatcher;
use op_mcp::tool_registry::ToolRegistry;
use simd_json::prelude::*;
use std::sync::Arc;
use zbus::interface;

pub struct CognitiveMcpInterface {
    registry: Arc<ToolRegistry>,
    dispatcher: Arc<CognitiveMethodDispatcher>,
}

impl CognitiveMcpInterface {
    pub fn new(registry: Arc<ToolRegistry>, dispatcher: Arc<CognitiveMethodDispatcher>) -> Self {
        Self { registry, dispatcher }
    }
}

#[interface(name = "org.opdbus.v1.plugins.CognitiveMcp")]
impl CognitiveMcpInterface {
    /// Dispatch a schema-declared method call to the appropriate cognitive backend.
    ///
    /// Called by `MutationEngine::dispatch_method_call` in op-grpc-bridge when
    /// a `PluginService.CallMethod` targets a cognitive plugin (qdrant, cozo, etc.).
    async fn call_method(
        &self,
        plugin_id: String,
        method: String,
        args_json: String,
    ) -> zbus::fdo::Result<String> {
        match self.dispatcher.dispatch(&plugin_id, &method, &args_json).await {
            Ok(result) => {
                let json = simd_json::to_string(&result)
                    .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))?;
                Ok(json)
            }
            Err(e) => {
                tracing::warn!(
                    plugin_id = %plugin_id,
                    method = %method,
                    error = %e,
                    "cognitive method dispatch failed"
                );
                Err(zbus::fdo::Error::Failed(e.to_string()))
            }
        }
    }

    /// List all tools from the MCP tool registry.
    async fn list_tools(&self) -> zbus::fdo::Result<String> {
        let defs = self.registry.list(0, usize::MAX, None).await;
        let arr: Vec<serde_json::Value> = defs
            .iter()
            .map(|d| {
                serde_json::json!({
                    "name": d.name,
                    "description": d.description,
                    "category": d.category
                })
            })
            .collect();
        serde_json::to_string(&arr).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get the input schema for a specific tool.
    async fn get_tool_schema(&self, name: String) -> zbus::fdo::Result<String> {
        match self.registry.get_definition(&name).await {
            Some(def) => simd_json::to_string(&def.input_schema)
                .map_err(|e| zbus::fdo::Error::Failed(e.to_string())),
            None => Ok("null".to_string()),
        }
    }

    /// Execute a tool by name via the legacy tool registry.
    async fn call_tool(&self, name: String, args_json: String) -> String {
        let args = match parse_simd(&args_json) {
            Ok(v) => v,
            Err(e) => return err_json(&e),
        };
        match self.registry.execute(&name, args).await {
            Ok(result) => simd_json::to_string(&result)
                .unwrap_or_else(|_| r#"{"error":"serialize failed"}"#.to_string()),
            Err(e) => err_json(&e.to_string()),
        }
    }
}

fn parse_simd(s: &str) -> Result<simd_json::OwnedValue, String> {
    let mut buf = s.as_bytes().to_vec();
    simd_json::from_slice(&mut buf).map_err(|e| e.to_string())
}

fn err_json(msg: &str) -> String {
    serde_json::json!({ "error": msg }).to_string()
}

