/// Register the cognitive method dispatcher on the system D-Bus.
///
/// This exposes `org.opdbus.v1.plugins.CognitiveMcp` at
/// `/org/opdbus/v1/plugins/cognitive_mcp` so that `op-grpc-bridge`'s
/// `MutationEngine::dispatch_method_call` can route cognitive plugin
/// method calls (qdrant.*, cozo.*, etc.) to this process via D-Bus.
///
/// Returns a `JoinHandle` so the caller can await the D-Bus service
/// alongside the HTTP/gRPC servers.
pub async fn start_dbus_service(&self) -> Result<tokio::task::JoinHandle<()>, Box<dyn std::error::Error>> {
    let dispatcher = Arc::new(CognitiveMethodDispatcher::new(
        self.qdrant_shuttle.clone(),
        self.cozo_shuttle.clone(),
        self.rag_pipeline.clone(),
    ));

    let interface = CognitiveMcpInterface::new(
        self.tool_registry.clone(),
        dispatcher,
    );

    let conn = zbus::Connection::system().await.map_err(|e| {
        format!("Failed to connect to system D-Bus for cognitive MCP interface: {e}")
    })?;

    conn.object_server()
        .at("/org/opdbus/v1/plugins/cognitive_mcp", interface)
        .await
        .map_err(|e| format!("Failed to register CognitiveMcp D-Bus interface: {e}"))?;

    tracing::info!(
        path = "/org/opdbus/v1/plugins/cognitive_mcp",
        "Cognitive MCP D-Bus interface registered — method dispatch available"
    );

    // Keep the connection alive for the lifetime of the process
    let handle = tokio::spawn(async move {
        // The connection is held alive by this task.  zbus handles
        // message dispatch internally via its own task pool, so we
        // just need to prevent the connection from being dropped.
        std::future::pending::<()>().await;
    });

    Ok(handle)
}

/// Run the cognitive MCP server over stdio (stdin/stdout JSON-RPC).

let server = CognitiveMcpServer::new(&cli.db).await?;

// Register the cognitive method dispatcher on the system D-Bus so that
// op-grpc-bridge can route qdrant.*/cozo.*/etc. method calls here.
if bind_config.dbus_enabled {
    match server.start_dbus_service().await {
        Ok(_handle) => {
            info!("D-Bus cognitive method dispatcher registered");
        }
        Err(e) => {
            warn!(
                error = %e,
                "Failed to register D-Bus cognitive method dispatcher — \
                 zcall dispatch for cognitive plugins will not work until D-Bus is available"
            );
        }
    }
}

