/// Dispatch a cognitive plugin method call to `op-cognitive-mcp` via the
/// system D-Bus.  The cognitive MCP process registers
/// `org.opdbus.v1.plugins.CognitiveMcp` at
/// `/org/opdbus/v1/plugins/cognitive_mcp` with a `CallMethod` D-Bus method
/// that routes to the appropriate shuttle or pipeline.
async fn dispatch_cognitive_via_dbus(
    &self,
    plugin_id: &str,
    method: &str,
    json_args: &str,
) -> anyhow::Result<serde_json::Value> {
    let conn = self.dbus_connection.get().ok_or_else(|| {
        anyhow::anyhow!(
            "D-Bus system connection not initialised — cannot dispatch \
             cognitive plugin '{plugin_id}' method '{method}'"
        )
    })?;

    tracing::debug!(
        plugin_id,
        method,
        "dispatching cognitive method via D-Bus to op-cognitive-mcp"
    );

    let reply = conn
        .call_method(
            Some("org.opdbus.v1"),
            "/org/opdbus/v1/plugins/cognitive_mcp",
            Some("org.opdbus.v1.plugins.CognitiveMcp"),
            "CallMethod",
            &(plugin_id, method, json_args),
        )
        .await
        .map_err(|e| {
            anyhow::anyhow!(
                "D-Bus CallMethod failed for {plugin_id}.{method}: {e}. \
                 Ensure op-cognitive-mcp is running and registered on the system bus."
            )
        })?;

    let result_json: String = reply
        .body
        .deserialize()
        .map_err(|e| anyhow::anyhow!("failed to deserialize D-Bus CallMethod reply: {e}"))?;

    let result: serde_json::Value = serde_json::from_str(&result_json)
        .map_err(|e| anyhow::anyhow!("failed to parse cognitive dispatch result JSON: {e}"))?;

    Ok(result)
}

