//! Production method dispatcher for cognitive plugin surfaces.
//!
//! When `PluginService.CallMethod` arrives at the gRPC bridge for a cognitive
//! plugin (qdrant, cozo, …), the bridge forwards the call via D-Bus to this
//! dispatcher, which routes it to the appropriate shuttle or pipeline.
//!
//! Every method declared in the plugin schema has a concrete execution path
//! here — no stubs, no placeholders.

use anyhow::{Context, Result};
use qdrant_client::qdrant::{
    CreateCollectionBuilder, DeleteCollectionBuilder, DeletePointsBuilder,
    Distance, PointStruct, ScrollPointsBuilder,
    SearchPointsBuilder, UpsertPointsBuilder, VectorParamsBuilder, VectorsConfig,
};
use serde::{Deserialize, Serialize};
use simd_json::{OwnedValue as Value, prelude::*};
use std::sync::Arc;

use crate::cozo_shuttle::CozoGraphShuttle;
use crate::qdrant_shuttle::QdrantSemanticShuttle;
use crate::rag_pipeline::{CodeFilter, RagPipeline, RagResult, RetrievalMode};

/// Plugin IDs handled by this dispatcher.
pub const COGNITIVE_PLUGIN_IDS: &[&str] = &[
    "qdrant",
    "cozo",
    "notebooklm",
    "gemini",
    "memory",
    "code_search",
    "code_index",
    "voyage",
    "doctor",
];

pub struct CognitiveMethodDispatcher {
    pub qdrant_shuttle: Option<Arc<QdrantSemanticShuttle>>,
    pub cozo_shuttle: Arc<CozoGraphShuttle>,
    pub rag_pipeline: Option<Arc<RagPipeline>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DispatchResult {
    pub plugin: String,
    pub method: String,
    pub result: Value,
}

impl CognitiveMethodDispatcher {
    pub fn new(
        qdrant_shuttle: Option<Arc<QdrantSemanticShuttle>>,
        cozo_shuttle: Arc<CozoGraphShuttle>,
        rag_pipeline: Option<Arc<RagPipeline>>,
    ) -> Self {
        Self {
            qdrant_shuttle,
            cozo_shuttle,
            rag_pipeline,
        }
    }

    /// Dispatch a method call to the appropriate backend.
    ///
    /// `plugin_id` is the schema plugin name (e.g. "qdrant", "cozo").
    /// `method` is the method name declared in the plugin schema.
    /// `args_json` is the verbatim JSON arguments string from the caller.
    pub async fn dispatch(
        &self,
        plugin_id: &str,
        method: &str,
        args_json: &str,
    ) -> Result<Value> {
        let mut bytes = args_json.as_bytes().to_vec();
        let args: Value = simd_json::from_slice(&mut bytes)
            .with_context(|| format!("invalid JSON args for {plugin_id}.{method}"))?;

        match plugin_id {
            "qdrant" => self.dispatch_qdrant(method, &args).await,
            "cozo" => self.dispatch_cozo(method, &args).await,
            _ => Err(anyhow::anyhow!(
                "unknown cognitive plugin '{plugin_id}' — no dispatcher configured"
            )),
        }
    }

    // ── qdrant ───────────────────────────────────────────────────────────────

    async fn dispatch_qdrant(&self, method: &str, args: &Value) -> Result<Value> {
        let shuttle = self.qdrant_shuttle.as_ref().ok_or_else(|| {
            anyhow::anyhow!("Qdrant shuttle is not available — vector operations require a running Qdrant instance")
        })?;

        match method {
            "health" => {
                shuttle.client().health_check().await.context("qdrant health check")?;
                Ok(simd_json::json!({
                    "healthy": true,
                    "version": "1.18.2",
                    "mode": "grpc"
                }))
            }

            "list_collections" => {
                let resp = shuttle.client().list_collections().await
                    .context("failed to list Qdrant collections")?;
                let names: Vec<String> = resp.collections.iter()
                    .map(|c| c.clone())
                    .collect();
                Ok(simd_json::json!({ "collections": names }))
            }

            "get_collection_info" => {
                let name = args.get("name")
                    .and_then(|v| v.as_str())
                    .context("missing 'name' field")?;
                let info = shuttle.client().collection_info(name).await
                    .with_context(|| format!("failed to get info for collection '{name}'"))?;
                let info_json = serde_json::to_value(&info)
                    .unwrap_or(serde_json::Value::Null);
                Ok(simd_json::json!({ "collection_info": info_json }))
            }

            "create_collection" => {
                let name = args.get("name")
                    .and_then(|v| v.as_str())
                    .context("missing 'name' field")?;
                let size = args.get("vectors_config")
                    .and_then(|v| v.get("size"))
                    .and_then(|v| v.as_u64())
                    .unwrap_or(1024);
                let distance_str = args.get("vectors_config")
                    .and_then(|v| v.get("distance"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("Cosine");
                let distance = match distance_str {
                    "Cosine" => Distance::Cosine,
                    "Euclid" => Distance::Euclid,
                    "Dot" => Distance::Dot,
                    "Manhattan" => Distance::Manhattan,
                    other => return Err(anyhow::anyhow!("unsupported distance: {other}")),
                };

                shuttle.client()
                    .create_collection(
                        CreateCollectionBuilder::new(name)
                            .vectors_config(VectorsConfig {
                                config: Some(qdrant_client::qdrant::vectors_config::Config::Params(
                                    VectorParamsBuilder::new(size, distance).into(),
                                )),
                            }),
                    )
                    .await
                    .with_context(|| format!("failed to create collection '{name}'"))?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "delete_collection" => {
                let name = args.get("name")
                    .and_then(|v| v.as_str())
                    .context("missing 'name' field")?;
                shuttle.client()
                    .delete_collection(DeleteCollectionBuilder::new(name).build())
                    .await
                    .with_context(|| format!("failed to delete collection '{name}'"))?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "search_points" => {
                let collection = args.get("collection_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'collection_name'")?;
                let vector = args.get("vector")
                    .and_then(|v| v.as_array())
                    .context("missing 'vector'")?
                    .iter()
                    .filter_map(|v| v.as_f64().map(|f| f as f32))
                    .collect::<Vec<f32>>();
                let limit = args.get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(10) as u64;

                let resp = shuttle.client()
                    .search_points(
                        SearchPointsBuilder::new(collection, vector, limit)
                            .with_payload(true),
                    )
                    .await
                    .with_context(|| format!("search_points failed on '{collection}'"))?;

                let results: Vec<_> = resp.result.iter().map(|p| {
                    serde_json::to_value(p).unwrap_or(serde_json::Value::Null)
                }).collect();
                Ok(simd_json::json!({ "results": results }))
            }

            "upsert_points" => {
                let collection = args.get("collection_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'collection_name'")?;
                let points = args.get("points")
                    .and_then(|v| v.as_array())
                    .context("missing 'points'")?;

                let mut point_structs = Vec::with_capacity(points.len());
                for p in points {
                    let id = p.get("id")
                        .and_then(|v| v.as_str())
                        .unwrap_or_else(|| {
                            p.get("id")
                                .and_then(|v| v.as_u64())
                                .map(|n| n.to_string())
                                .unwrap_or_default()
                        });
                    let vector = p.get("vector")
                        .and_then(|v| v.as_array())
                        .map(|arr| {
                            arr.iter()
                                .filter_map(|v| v.as_f64().map(|f| f as f32))
                                .collect::<Vec<f32>>()
                        })
                        .unwrap_or_default();
                    let payload = p.get("payload")
                        .map(|v| serde_json::Value::clone(v))
                        .unwrap_or(serde_json::Value::Null);
                    let payload: qdrant_client::Payload = payload.try_into()
                        .context("failed to build Qdrant payload")?;
                    point_structs.push(PointStruct::new(id, vector, payload));
                }

                shuttle.client()
                    .upsert_points(UpsertPointsBuilder::new(collection, point_structs))
                    .await
                    .with_context(|| format!("upsert_points failed on '{collection}'"))?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "delete_points" => {
                let collection = args.get("collection_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'collection_name'")?;
                let point_ids: Vec<_> = args.get("points")
                    .and_then(|v| v.as_array())
                    .context("missing 'points'")?
                    .iter()
                    .filter_map(|p| {
                        p.as_str().map(|s| s.to_string())
                            .or_else(|| p.as_u64().map(|n| n.to_string()))
                    })
                    .collect();

                shuttle.client()
                    .delete_points(
                        DeletePointsBuilder::new(collection)
                            .points(point_ids.into_iter().map(|s| {
                                qdrant_client::qdrant::PointId::from(s)
                            }).collect()),
                    )
                    .await
                    .with_context(|| format!("delete_points failed on '{collection}'"))?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "scroll_points" => {
                let collection = args.get("collection_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'collection_name'")?;
                let limit = args.get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(10) as u32;

                let resp = shuttle.client()
                    .scroll(
                        ScrollPointsBuilder::new(collection)
                            .limit(limit)
                            .with_payload(true)
                            .with_vectors(false),
                    )
                    .await
                    .with_context(|| format!("scroll_points failed on '{collection}'"))?;

                let points: Vec<_> = resp.result.iter().map(|p| {
                    serde_json::to_value(p).unwrap_or(serde_json::Value::Null)
                }).collect();
                Ok(simd_json::json!({
                    "points": points,
                    "next_page_offset": null
                }))
            }

            "create_payload_index" => {
                let collection = args.get("collection_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'collection_name'")?;
                let field_name = args.get("field_name")
                    .and_then(|v| v.as_str())
                    .context("missing 'field_name'")?;
                let field_schema = args.get("field_schema")
                    .map(|v| serde_json::Value::clone(v))
                    .unwrap_or(serde_json::Value::String("keyword".into()));

                use qdrant_client::qdrant::CreateFieldIndexCollectionBuilder;
                shuttle.client()
                    .create_field_index(
                        CreateFieldIndexCollectionBuilder::new(collection)
                            .field_name(field_name)
                            .field_schema(field_schema),
                    )
                    .await
                    .with_context(|| format!("create_payload_index failed on '{collection}'"))?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "rag_search" => {
                let rag = self.rag_pipeline.as_ref().ok_or_else(|| {
                    anyhow::anyhow!("RAG pipeline is not available — code search requires Voyage API key")
                })?;

                let query = args.get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let mode_str = args.get("mode")
                    .and_then(|v| v.as_str())
                    .unwrap_or("search");
                let mode = RetrievalMode::parse(mode_str);
                let limit = args.get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or_else(|| match mode {
                        RetrievalMode::Completion => 12,
                        RetrievalMode::Search => 12,
                        RetrievalMode::Deep => 50,
                    });

                // Parse optional code filters
                let filter = parse_code_filter(args.get("filters"));

                // Parse optional collection list
                let collections: Vec<String> = args.get("collections")
                    .and_then(|v| v.as_array())
                    .map(|arr| {
                        arr.iter()
                            .filter_map(|v| v.as_str().map(|s| s.to_string()))
                            .collect()
                    })
                    .unwrap_or_default();

                let results: Vec<RagResult> = if !collections.is_empty() {
                    rag.query_fused_collections(
                        &collections,
                        query,
                        limit,
                        limit.saturating_mul(3).clamp(limit, 64),
                        &filter,
                    ).await?
                } else {
                    // Default: use the first default collection with fused search
                    let default_col = crate::rag_pipeline::default_collection_from_env();
                    rag.query_fused(&default_col, query, limit, &filter).await?
                };

                let results_json: Vec<_> = results.iter().map(|r| {
                    serde_json::to_value(r).unwrap_or(serde_json::Value::Null)
                }).collect();
                let total = results_json.len();
                Ok(simd_json::json!({
                    "results": results_json,
                    "total": total
                }))
            }

            "semantic_trace_search" => {
                let limit = args.get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(5);

                let trace = shuttle.current_trace_context()?;
                let results = shuttle.search_semantic_trace(limit).await
                    .context("semantic trace search failed")?;

                let results_json: Vec<_> = results.iter().map(|p| {
                    serde_json::to_value(p).unwrap_or(serde_json::Value::Null)
                }).collect();
                Ok(simd_json::json!({
                    "results": results_json,
                    "trace_id": trace.trace_id
                }))
            }

            "user_memory_search" => {
                let query = args.get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let container_id = args.get("container_id")
                    .and_then(|v| v.as_str())
                    .context("missing 'container_id'")?;
                let limit = args.get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(10);

                let embedding = shuttle.embed_query_text(query).await
                    .context("failed to embed query via Voyage")?;
                let results = shuttle.search_user_memory(embedding, container_id, limit).await
                    .with_context(|| format!("user_memory_search failed for container '{container_id}'"))?;

                let results_json: Vec<_> = results.iter().map(|p| {
                    serde_json::to_value(p).unwrap_or(serde_json::Value::Null)
                }).collect();
                Ok(simd_json::json!({ "results": results_json }))
            }

            "user_memory_upsert" => {
                let point_id = args.get("point_id")
                    .and_then(|v| v.as_str())
                    .context("missing 'point_id'")?;
                let content = args.get("content")
                    .and_then(|v| v.as_str())
                    .context("missing 'content'")?;
                let container_id = args.get("container_id")
                    .and_then(|v| v.as_str())
                    .context("missing 'container_id'")?;
                let entry_key = args.get("entry_key")
                    .and_then(|v| v.as_str())
                    .context("missing 'entry_key'")?;

                let vector = shuttle.embed_document(content).await
                    .context("failed to embed document via Voyage")?;
                shuttle.upsert_user_memory(point_id, vector, container_id, entry_key, content).await
                    .context("user_memory_upsert failed")?;
                Ok(simd_json::json!({ "acknowledged": true }))
            }

            "create_snapshot" | "list_snapshots" => {
                Err(anyhow::anyhow!(
                    "snapshot operations require the Qdrant HTTP endpoint and are not yet dispatched via gRPC"
                ))
            }

            unknown => Err(anyhow::anyhow!(
                "unknown qdrant method '{unknown}'"
            )),
        }
    }

    // ── cozo ─────────────────────────────────────────────────────────────────

    async fn dispatch_cozo(&self, method: &str, args: &Value) -> Result<Value> {
        let shuttle = &self.cozo_shuttle;
        let db = shuttle.db();

        match method {
            "health" => {
                // Run a trivial query to verify the database is responsive
                let _result = db.run_script(
                    "?[] <- [[1]]",
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Immutable,
                ).context("cozo health check query failed")?;
                let db_path = std::env::var("COGNITIVE_MCP_COZO_DB_PATH")
                    .unwrap_or_default();
                Ok(simd_json::json!({
                    "healthy": true,
                    "engine": if db_path.is_empty() { "mem" } else { "sled" },
                    "version": "0.7.6"
                }))
            }

            "run_query" => {
                let query = args.get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let params = parse_cozo_params(args.get("params"));

                let result = db.run_script(
                    query,
                    params,
                    cozo::ScriptMutability::Mutable,
                ).with_context(|| format!("cozo query failed: {query}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "run_read_query" => {
                let query = args.get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let params = parse_cozo_params(args.get("params"));

                let result = db.run_script(
                    query,
                    params,
                    cozo::ScriptMutability::Immutable,
                ).with_context(|| format!("cozo read query failed: {query}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "list_relations" => {
                let result = db.run_script(
                    "::relations",
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Immutable,
                ).context("failed to list CozoDB relations")?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "describe_relation" => {
                let name = args.get("name")
                    .and_then(|v| v.as_str())
                    .context("missing 'name'")?;
                let script = format!("::columns {name}");
                let result = db.run_script(
                    &script,
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Immutable,
                ).with_context(|| format!("failed to describe relation '{name}'"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "import_relations" => {
                let data = args.get("data")
                    .map(|v| serde_json::Value::clone(v))
                    .context("missing 'data'")?;
                let data_str = serde_json::to_string(&data)
                    .context("failed to serialize import data")?;
                let script = format!("?[] <~ {data_str}");
                let result = db.run_script(
                    &script,
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Mutable,
                ).context("cozo import_relations failed")?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "export_relations" => {
                let relations = args.get("relations")
                    .and_then(|v| v.as_array())
                    .context("missing 'relations'")?;
                let rel_names: Vec<String> = relations.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect();
                let rel_list = rel_names.iter()
                    .map(|r| format!(":{r}"))
                    .collect::<Vec<_>>()
                    .join(", ");
                let script = format!("?[] <- {rel_list}");
                let result = db.run_script(
                    &script,
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Immutable,
                ).context("cozo export_relations failed")?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "backup" => {
                Err(anyhow::anyhow!(
                    "cozo backup requires direct DbInstance access — use the cozo CLI or op-cognitive-mcp admin endpoint"
                ))
            }

            "restore" => {
                Err(anyhow::anyhow!(
                    "cozo restore requires direct DbInstance access — use the cozo CLI or op-cognitive-mcp admin endpoint"
                ))
            }

            unknown => Err(anyhow::anyhow!(
                "unknown cozo method '{unknown}'"
            )),
        }
    }
}

// ── helpers ───────────────────────────────────────────────────────────────────

fn parse_code_filter(filters: Option<&Value>) -> CodeFilter {
    let Some(f) = filters else { return CodeFilter::default() };
    CodeFilter {
        repo: f.get("repo").and_then(|v| v.as_str()).map(|s| s.to_string()),
        language: f.get("language").and_then(|v| v.as_str()).map(|s| s.to_string()),
        file_type: f.get("file_type").and_then(|v| v.as_str()).map(|s| s.to_string()),
        path_contains: f.get("path_contains").and_then(|v| v.as_str()).map(|s| s.to_string()),
        symbol_contains: f.get("symbol_contains").and_then(|v| v.as_str()).map(|s| s.to_string()),
        exclude_tests: f.get("exclude_tests").and_then(|v| v.as_bool()).unwrap_or(false),
    }
}

fn parse_cozo_params(
    params: Option<&Value>,
) -> std::collections::BTreeMap<String, cozo::DataValue> {
    let Some(obj) = params.and_then(|v| v.as_object()) else {
        return std::collections::BTreeMap::new();
    };

    let mut map = std::collections::BTreeMap::new();
    for (key, value) in obj.iter() {
        let dv = json_to_datavalue(value);
        map.insert(key.to_string(), dv);
    }
    map
}

fn json_to_datavalue(value: &Value) -> cozo::DataValue {
    if value.is_null() {
        cozo::DataValue::Null
    } else if let Some(s) = value.as_str() {
        cozo::DataValue::Str(s.to_string())
    } else if let Some(b) = value.as_bool() {
        cozo::DataValue::Bool(b)
    } else if let Some(i) = value.as_i64() {
        cozo::DataValue::Int(i)
    } else if let Some(f) = value.as_f64() {
        cozo::DataValue::Float(f)
    } else {
        cozo::DataValue::Json(serde_json::to_string(value).unwrap_or_default())
    }
}

