                let mut point_structs = Vec::with_capacity(points.len());
                for p in points {
                    let id = p
                        .get("id")
                        .and_then(|v| v.as_str())
                        .unwrap_or_else(|| {
                            p.get("id")
                                .and_then(|v| v.as_u64())
                                .map(|n| n.to_string())
                                .unwrap_or_default()
                        });
                    let vector = p
                        .get("vector")
                        .and_then(|v| v.as_array())
                        .map(|arr| {
                            arr.iter()
                                .filter_map(|v| v.as_f64().map(|f| f as f32))
                                .collect::<Vec<f32>>()
                        })
                        .unwrap_or_default();
                    let payload = p
                        .get("payload")
                        .map(|v| serde_json::Value::clone(v))
                        .unwrap_or(serde_json::Value::Null);
                    let payload: qdrant_client::Payload =
                        payload.try_into().context("failed to build Qdrant payload")?;
                    point_structs.push(PointStruct::new(id, vector, payload));
                }

                shuttle
                    .client()
                    .upsert_points(UpsertPointsBuilder::new(collection, point_structs))
