    // ── cozo ─────────────────────────────────────────────────────────────────

    async fn dispatch_cozo(&self, method: &str, args: &Value) -> Result<Value> {
        let shuttle = &self.cozo_shuttle;
        let db = shuttle.db();

        match method {
            "health" => {
                db.run_script(
                    "?[] <- [[1]]",
                    std::collections::BTreeMap::new(),
                    cozo::ScriptMutability::Immutable,
                )
                .map_err(|e| anyhow::anyhow!("cozo health check query failed: {e}"))?;

                let db_path = std::env::var("COGNITIVE_MCP_COZO_DB_PATH").unwrap_or_default();
                Ok(simd_json::json!({
                    "healthy": true,
                    "engine": if db_path.is_empty() { "mem" } else { "sled" },
                    "version": "0.7.6"
                }))
            }

            "run_query" => {
                let query = args
                    .get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let params = parse_cozo_params(args.get("params"));

                let result = db
                    .run_script(query, params, cozo::ScriptMutability::Mutable)
                    .map_err(|e| anyhow::anyhow!("cozo query failed: {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "run_read_query" => {
                let query = args
                    .get("query")
                    .and_then(|v| v.as_str())
                    .context("missing 'query'")?;
                let params = parse_cozo_params(args.get("params"));

                let result = db
                    .run_script(query, params, cozo::ScriptMutability::Immutable)
                    .map_err(|e| anyhow::anyhow!("cozo read query failed: {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "list_relations" => {
                let result = db
                    .run_script(
                        "::relations",
                        std::collections::BTreeMap::new(),
                        cozo::ScriptMutability::Immutable,
                    )
                    .map_err(|e| anyhow::anyhow!("failed to list CozoDB relations: {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "describe_relation" => {
                let name = args
                    .get("name")
                    .and_then(|v| v.as_str())
                    .context("missing 'name'")?;
                let script = format!("::columns {name}");
                let result = db
                    .run_script(
                        &script,
                        std::collections::BTreeMap::new(),
                        cozo::ScriptMutability::Immutable,
                    )
                    .map_err(|e| anyhow::anyhow!("failed to describe relation '{name}': {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "import_relations" => {
                let data = args
                    .get("data")
                    .map(|v| serde_json::Value::clone(v))
                    .context("missing 'data'")?;
                let data_str = serde_json::to_string(&data)
                    .context("failed to serialize import data")?;
                let script = format!("?[] <~ {data_str}");
                let result = db
                    .run_script(
                        &script,
                        std::collections::BTreeMap::new(),
                        cozo::ScriptMutability::Mutable,
                    )
                    .map_err(|e| anyhow::anyhow!("cozo import_relations failed: {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "export_relations" => {
                let relations = args
                    .get("relations")
                    .and_then(|v| v.as_array())
                    .context("missing 'relations'")?;
                let rel_names: Vec<String> = relations
                    .iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect();
                let rel_list = rel_names
                    .iter()
                    .map(|r| format!(":{r}"))
                    .collect::<Vec<_>>()
                    .join(", ");
                let script = format!("?[] <- [{rel_list}]");
                let result = db
                    .run_script(
                        &script,
                        std::collections::BTreeMap::new(),
                        cozo::ScriptMutability::Immutable,
                    )
                    .map_err(|e| anyhow::anyhow!("cozo export_relations failed: {e}"))?;
                let json = crate::cozo_shuttle::named_rows_to_json(result);
                Ok(json)
            }

            "backup" => Err(anyhow::anyhow!(
                "cozo backup requires direct DbInstance access — use the cozo CLI or op-cognitive-mcp admin endpoint"
            )),

            "restore" => Err(anyhow::anyhow!(
                "cozo restore requires direct DbInstance access — use the cozo CLI or op-cognitive-mcp admin endpoint"
            )),

            unknown => Err(anyhow::anyhow!("unknown cozo method '{unknown}'")),
        }
    }
}

