/// Extract a Qdrant `PointId` as a JSON value (string UUID or numeric).
fn point_id_to_json(id: &Option<qdrant_client::qdrant::PointId>) -> serde_json::Value {
    match id {
        Some(pid) => match &pid.point_id_options {
            Some(PointIdOptions::Num(n)) => serde_json::json!(n),
            Some(PointIdOptions::Uuid(s)) => serde_json::json!(s),
            None => serde_json::Value::Null,
        },
        None => serde_json::Value::Null,
    }
}

/// Convert a Qdrant payload HashMap to a JSON object.
fn payload_to_json(
    payload: &std::collections::HashMap<String, qdrant_client::qdrant::Value>,
) -> serde_json::Value {
    let mut map = serde_json::Map::new();
    for (key, value) in payload {
        // qdrant::Value -> prost Value -> convert to serde_json::Value
        // The qdrant Value type has a kind field with various types.
        // For simplicity, we serialize it through the prost type.
        let json_val = qdrant_value_to_json(value);
        map.insert(key.clone(), json_val);
    }
    serde_json::Value::Object(map)
}

/// Convert a qdrant::Value to a serde_json::Value.
fn qdrant_value_to_json(value: &qdrant_client::qdrant::Value) -> serde_json::Value {
    use qdrant_client::qdrant::value::Kind;
    match &value.kind {
        Some(Kind::NullValue(_)) => serde_json::Value::Null,
        Some(Kind::BoolValue(b)) => serde_json::json!(b),
        Some(Kind::IntegerValue(i)) => serde_json::json!(i),
        Some(Kind::DoubleValue(d)) => serde_json::json!(d),
        Some(Kind::StringValue(s)) => serde_json::json!(s),
        Some(Kind::StructValue(s)) => {
            let mut map = serde_json::Map::new();
            for (k, v) in &s.fields {
                map.insert(k.clone(), qdrant_value_to_json(v));
            }
            serde_json::Value::Object(map)
        }
        Some(Kind::ListValue(l)) => {
            serde_json::Value::Array(l.values.iter().map(qdrant_value_to_json).collect())
        }
        None => serde_json::Value::Null,
    }
}

fn parse_code_filter(filters: Option<&Value>) -> CodeFilter {
    let Some(f) = filters else {
        return CodeFilter::default();
    };
    CodeFilter {
        repo: f
            .get("repo")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string()),
        language: f
            .get("language")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string()),
        file_type: f
            .get("file_type")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string()),
        path_contains: f
            .get("path_contains")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string()),
        symbol_contains: f
            .get("symbol_contains")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string()),
        exclude_tests: f
            .get("exclude_tests")
            .and_then(|v| v.as_bool())
            .unwrap_or(false),
    }
}

fn parse_cozo_params(params: Option<&Value>) -> std::collections::BTreeMap<String, cozo::DataValue> {
    let Some(obj) = params.and_then(|v| v.as_object()) else {
        return std::collections::BTreeMap::new();
    };

    let mut map = std::collections::BTreeMap::new();
    for (key, value) in obj.iter() {
        let dv = json_to_datavalue(value);
        map.insert(key.to_string(), dv);
    }
    map
}

fn json_to_datavalue(value: &Value) -> cozo::DataValue {
    use cozo::{DataValue, JsonData, Num};

    if value.is_null() {
        DataValue::Null
    } else if let Some(b) = value.as_bool() {
        DataValue::Bool(b)
    } else if let Some(i) = value.as_i64() {
        DataValue::Num(Num::Int(i))
    } else if let Some(f) = value.as_f64() {
        DataValue::Num(Num::Float(f))
    } else if let Some(s) = value.as_str() {
        DataValue::Str(s.to_string())
    } else {
        let json_str = serde_json::to_string(value).unwrap_or_default();
        DataValue::Json(JsonData(
            serde_json::from_str(&json_str).unwrap_or(serde_json::Value::Null),
        ))
    }
}

