/// Convert a simd_json::OwnedValue to a serde_json::Value.
fn simd_to_serde_json(v: &Value) -> serde_json::Value {
    let s = simd_json::to_string(v).unwrap_or_else(|_| "null".to_string());
    serde_json::from_str(&s).unwrap_or(serde_json::Value::Null)
}

/// Convert a serde_json::Value to a simd_json::OwnedValue.
fn serde_to_simd_json(v: &serde_json::Value) -> Value {
    let s = serde_json::to_string(v).unwrap_or_else(|_| "null".to_string());
    let mut bytes = s.into_bytes();
    simd_json::from_slice(&mut bytes).unwrap_or(Value::Null)
}

