//! Schema-driven tool registry — populates the MCP ToolRegistry from plugin
//! schemas instead of manual `register_*` calls.
//!
//! Each `MethodDecl` in a cognitive plugin's `PluginSchema` becomes a tool in
//! the registry, named `{plugin_id}.{method}`. Execution routes through the
//! `CognitiveMethodDispatcher`, which calls the appropriate shuttle or pipeline.

use anyhow::Result;
use async_trait::async_trait;
use op_mcp::tool_registry::{BoxedTool, Tool, ToolRegistry};
use op_plugins::state_plugins::{
    cozo::cozo_schema, cognitive_mcp::cognitive_mcp_schema, qdrant::qdrant_schema,
};
use op_state_store::PluginSchema;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::sync::Arc;

use crate::method_dispatch::CognitiveMethodDispatcher;

/// A tool whose execution is routed through the cognitive method dispatcher.
pub struct SchemaDrivenTool {
    tool_name: String,
    description: String,
    input_schema: Value,
    category: String,
    namespace: String,
    plugin_id: String,
    method: String,
    dispatcher: Arc<CognitiveMethodDispatcher>,
}

impl SchemaDrivenTool {
    pub fn new(
        plugin_id: &str,
        method: &str,
        schema: &PluginSchema,
        dispatcher: Arc<CognitiveMethodDispatcher>,
    ) -> Self {
        let tool_name = format!("{plugin_id}.{method}");
        let method_decl = schema.methods.get(method);
        let description = method_decl
            .map(|d| {
                if d.description.is_empty() {
                    format!("{} {}", schema.description, method)
                } else {
                    d.description.clone()
                }
            })
            .unwrap_or_else(|| format!("{plugin_id}.{method}"));

        let input_schema = method_decl
            .map(|d| d.args.clone())
            .unwrap_or_else(|| simd_json::json!({}));

        Self {
            tool_name,
            description,
            input_schema,
            category: schema.category.clone(),
            namespace: plugin_id.to_string(),
            plugin_id: plugin_id.to_string(),
            method: method.to_string(),
            dispatcher,
        }
    }
}

#[async_trait]
impl Tool for SchemaDrivenTool {
    fn name(&self) -> &str {
        &self.tool_name
    }

    fn description(&self) -> &str {
        &self.description
    }

    fn input_schema(&self) -> Value {
        self.input_schema.clone()
    }

    fn category(&self) -> &str {
        &self.category
    }

    fn namespace(&self) -> &str {
        &self.namespace
    }

    fn tags(&self) -> Vec<String> {
        vec![self.plugin_id.clone(), self.method.clone()]
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let args_json = simd_json::to_string(&input).unwrap_or_else(|_| "{}".to_string());
        self.dispatcher
            .dispatch(&self.plugin_id, &self.method, &args_json)
            .await
    }
}

/// Register all cognitive plugin methods as tools in the registry.
///
/// This replaces the manual `register_notebooklm_tools()`,
/// `register_code_tools()`, `register_agent_tools()`, and
/// `register_typed_tools()` calls. Every method declared in a cognitive
/// plugin schema becomes a discoverable tool.
pub async fn register_schema_driven_tools(
    registry: &ToolRegistry,
    dispatcher: Arc<CognitiveMethodDispatcher>,
) -> Result<usize> {
    let schemas: Vec<(&str, PluginSchema)> = vec![
        ("qdrant", qdrant_schema()),
        ("cozo", cozo_schema()),
        ("cognitive_mcp", cognitive_mcp_schema()),
    ];

    let mut count = 0;
    for (plugin_id, schema) in schemas {
        for (method_name, _decl) in &schema.methods {
            let tool = Arc::new(SchemaDrivenTool::new(
                plugin_id,
                method_name,
                &schema,
                dispatcher.clone(),
            )) as BoxedTool;
            registry.register(tool).await?;
            count += 1;
        }
        tracing::info!(
            plugin_id,
            methods = schema.methods.len(),
            "Registered schema-driven tools for cognitive plugin"
        );
    }

    tracing::info!(total = count, "Schema-driven tool registration complete");
    Ok(count)
}

